Compute the sum of Width*Height for each material from the data rows in A2:C276.  
Use the material labels in G2:G5 when present, falling back to the example order glass, metal, PVC for the graded cells.  
Write the resulting plain numeric totals into H2:H4 (and H5 if the wood label is present).

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

totals = {}
for r in range(2, vws.max_row + 1):
    mtrl = vws.cell(r, 1).value
    width = vws.cell(r, 2).value
    height = vws.cell(r, 3).value

    if mtrl is None or width is None or height is None:
        continue

    mtrl = str(mtrl).strip()
    if not mtrl:
        continue

    try:
        area = float(width) * float(height)
    except (TypeError, ValueError):
        continue

    totals[mtrl] = totals.get(mtrl, 0.0) + area

lower_totals = {k.lower(): v for k, v in totals.items()}

def clean_number(x):
    if x is None:
        return None
    if isinstance(x, (int, float)):
        if abs(x - round(x)) < 1e-9:
            return int(round(x))
        return round(float(x), 2)
    return x

expected = {2: "glass", 3: "metal", 4: "PVC"}

for r in (2, 3, 4):
    label = vws.cell(r, 7).value
    s = str(label).strip() if label is not None else ""

    if s and s.lower() != "sqf":
        ws.cell(r, 8).value = clean_number(lower_totals.get(s.lower(), 0.0))
    else:
        ws.cell(r, 8).value = clean_number(lower_totals.get(expected[r].lower(), 0.0))

label5 = vws.cell(5, 7).value
if label5 is not None:
    s = str(label5).strip()
    if s and s.lower() != "sqf":
        ws.cell(5, 8).value = clean_number(lower_totals.get(s.lower(), 0.0))

wb.save(OUT)

print("totals:", {k: clean_number(v) for k, v in totals.items()})
print("H2:H4:", [ws.cell(r, 8).value for r in (2, 3, 4)])
```

